<?php
namespace App\Services\Automation\Handlers;
use App\Models\AutomationRun; use App\Models\OzonAccount; use App\Models\OzonTaxonomyNode; use App\Services\Automation\AutomationHandlerInterface; use App\Services\Automation\AutomationProgressReporterInterface; use App\Services\Ozon\OzonTaxonomyService;
class OzonTaxonomySyncHandler implements AutomationHandlerInterface { public function __construct(private readonly OzonTaxonomyService $service) {} public function handle(AutomationRun $run, AutomationProgressReporterInterface $progress, bool $dryRun=false): array { $progress->start(1,'Загрузка taxonomy Ozon.'); $nodeId=(int)($run->context['ozon_taxonomy_node_id'] ?? 0); if($nodeId){$result=$this->service->syncAttributes(OzonTaxonomyNode::query()->findOrFail($nodeId),$run);}else{$account=OzonAccount::query()->findOrFail((int)($run->context['ozon_account_id'] ?? 0));$tree=$this->service->syncTree($account,$run);$attributes=$this->service->syncAllAttributes($account,$run);$result=['successful'=>true,'processed_items'=>(int)$tree['processed_items']+(int)$attributes['processed_items'],'processed_nodes'=>(int)$tree['processed_items'],'processed_types'=>(int)$attributes['processed_types'],'processed_attributes'=>(int)$attributes['processed_items']];} $processed=(int)$result['processed_items']; $progress->setProgress($processed,$processed,'Taxonomy Ozon загружена.'); return [...$result,'total_items'=>$processed,'message'=>'Taxonomy Ozon загружена.']; } }
